// --- HABILIDADE DA RACA ---
std::string Mahoraga::getNameSkillRace() const { return "A Roda da Adaptacao"; }
std::string Mahoraga::getDescriptionSkillRace() const { return "Adapta-se ao alvo. Apos sofrer 10 parrys perfeitos, torna-se Imparavel."; }

// --- MECANICA DE ADAPTACAO ---
void Mahoraga::onCausingDamage(Character* attacker, Character* target, int damageCaused) {
    // Efeito popup de texto piscante
    CombatScreen::addFixedMessage(CombatScreen::combatMargin() + "\033[5m" + Appearance::color(Color::YELLOW) + "* KLINK! *" + Appearance::color(Color::RESET) + " A Roda gira...\n");

    // Adaptacao de Defesa
    int strengthDexteritySum = target->getStrength() + target->getDexterity();
    int intelligenceWisdomSum = target->getIntelligence() + target->getWisdom();
    
    if (strengthDexteritySum >= intelligenceWisdomSum) {
        if (attacker->getResistance() < 50) {
            attacker->changeStaticAttribute(AttributeType::Strength, 5);
            attacker->changeStaticAttribute(AttributeType::Dexterity, 5);
            attacker->changeStaticAttribute(AttributeType::Resistance, 5);
            attacker->changeStaticAttribute(AttributeType::Constitution, 5);
            Appearance::registerBattleLog(DialogueFunctions::formatSkillMsg("A Roda gira... Mahoraga adaptou-se ao combate fisico, ganhando atributos ofensivos e defensivos!", Color::MAGENTA));
        } else {
            Appearance::registerBattleLog(DialogueFunctions::formatSkillMsg("A Roda gira... A adaptacao fisica de Mahoraga atingiu seu limite...", Color::MAGENTA));
        }
    } else {
        if (attacker->getWisdom() < 50) {
            attacker->changeStaticAttribute(AttributeType::Intelligence, 5);
            attacker->changeStaticAttribute(AttributeType::Dexterity, 5);
            attacker->changeStaticAttribute(AttributeType::Wisdom, 5);
            attacker->changeStaticAttribute(AttributeType::Constitution, 5);
            Appearance::registerBattleLog(DialogueFunctions::formatSkillMsg("A Roda gira... Mahoraga adaptou-se a sua magia, ganhando atributos magicos e vitais!", Color::MAGENTA));
        } else {
            Appearance::registerBattleLog(DialogueFunctions::formatSkillMsg("A Roda gira... A adaptacao magica de Mahoraga atingiu seu limite...", Color::MAGENTA));
        }
    }

    // Cura
    int healing = attacker->getMaxHealth() * 0.05; 
    attacker->modifyHealth(healing);
    Appearance::registerBattleLog(DialogueFunctions::formatSkillMsg("Mahoraga regenerou " + std::to_string(healing) + " HP", Color::GREEN));

    // Limpeza de debuffs
    std::vector<EffectID> effects;
    attacker->getIDsEffectsAssets(effects);
    if (!effects.empty()) {
        attacker->cleanEffects();
        Appearance::registerBattleLog(DialogueFunctions::formatSkillMsg("Mahoraga adaptou-se a todos os status negativos", Color::WHITE));
    }
}

void Mahoraga::onSufferPerfectParry() {
    parrysSuffered++;
    if (parrysSuffered == 10) {
        CombatScreen::addFixedMessage(CombatScreen::combatMargin() + "\033[5m" + Appearance::color(Color::YELLOW) + "* KLINK! *" + Appearance::color(Color::RESET) + " A Roda gira...\n");
        Appearance::registerBattleLog(DialogueFunctions::formatSkillMsg("A Roda gira... Mahoraga adaptou-se aos seus reflexos! Seus ataques agora sao IMPARAVEIS!", Color::BG_RED));
    }
}

void Mahoraga::onAttackBlockedByShield() {
    if (defensesWithShieldSuffered < 3) {
        defensesWithShieldSuffered++;
        if (defensesWithShieldSuffered == 3) {
            CombatScreen::addFixedMessage(CombatScreen::combatMargin() + "\033[5m" + Appearance::color(Color::YELLOW) + "* KLINK! *" + Appearance::color(Color::RESET) + " A Roda gira...\n");
            Appearance::registerBattleLog(DialogueFunctions::formatSkillMsg("A Roda gira... Mahoraga adaptou-se a sua defesa! Seus ataques agora perfuram escudos!", Color::BG_RED));
        }
    }
}

bool Mahoraga::ignoreParry() const {
    return parrysSuffered >= 10;
}

bool Mahoraga::ignoreShield() const {
    return defensesWithShieldSuffered >= 3;
}

